(function () {
  'use strict';
  const engine = window.FraudEngine;
  const scenarioMeta = { ROUTINE_LEGITIMATE: ['Routine legitimate','Expected low risk and approval'], LEGITIMATE_UNUSUAL_VERIFY: ['Unusual but legitimate','Verification preserves a good purchase'], SUBTLE_FRAUD_VERIFY: ['Subtle fraud','Customer denial stops uncertain fraud'], OBVIOUS_FRAUD_DECLINE: ['Obvious fraud','Strong signals trigger a decline'], TRAVEL_NOTICE_RISK_REDUCTION: ['Travel notice','Known travel lowers geographic risk'], LOW_SIGNAL_FRAUD_EDGE_CASE: ['Low-signal fraud','A visible model limitation'] };
  const order = Object.keys(scenarioMeta); const exactMoney = new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'});
  let transactions = [], transaction, result; const indexes = {}; const el = id => document.getElementById(id); const escapeHtml = value => String(value).replace(/[&<>'"]/g, character => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[character])); const rowsFor = scenario => transactions.filter(item => item.scenario_type === scenario); const statusClass = action => action === 'APPROVE' ? 'fd-approve-text' : action === 'VERIFY' ? 'fd-verify-text' : 'fd-decline-text'; const statusIcon = action => action === 'APPROVE' ? '✓' : action === 'VERIFY' ? '◷' : '×';
  function displayValue(item,key){if(key==='amount_usd'||key==='avg_transaction_amount_30d')return exactMoney.format(Number(item[key]));if(key==='amount_vs_avg_ratio')return `${Number(item[key]).toFixed(2)}×`;if(key==='distance_from_home_miles')return `${Number(item[key]).toLocaleString()} mi`;if(key==='location')return `${item.city}, ${item.state_or_region}, ${item.country}`;return (item[key]||'—').replaceAll('_',' ');}
  function renderDetails(){const fields=[['Transaction ID','transaction_id'],['Customer ID','customer_id'],['Merchant','merchant_name'],['Merchant category','merchant_category'],['Amount','amount_usd'],['Location','location'],['Channel','channel'],['Card present','card_present'],['Trusted device','device_trusted'],['New device','new_device'],['Customer average','avg_transaction_amount_30d'],['Amount vs. average','amount_vs_avg_ratio'],['Distance from home','distance_from_home_miles'],['Transactions in last hour','txn_count_last_1h'],['Travel notice','travel_notice']];el('transaction-label').textContent=transaction.transaction_id;el('transaction-details').innerHTML=fields.map(([label,key])=>`<div><dt>${label}</dt><dd>${escapeHtml(displayValue(transaction,key))}</dd></div>`).join('');}
  function renderScore(){const action=result.initialAction;const comparison=result.score===Number(transaction.risk_score)&&action===transaction.initial_action;el('score-content').innerHTML=`<div class="fd-score-layout"><div class="fd-gauge fd-gauge-${action.toLowerCase()}" style="--score:${result.score*3.6}deg" role="img" aria-label="Risk score ${result.score} out of 100, ${action}"><div><strong>${result.score}</strong><span>/ 100</span></div></div><div><small>INITIAL DECISION</small><strong class="fd-status ${statusClass(action)}">${statusIcon(action)} ${action}</strong><p>${action==='VERIFY'?'Pause and request customer confirmation.':action==='APPROVE'?'Allow the transaction with no added friction.':'Block the transaction based on strong combined signals.'}</p></div></div><div class="fd-explanation"><strong>Why this decision?</strong><p>${escapeHtml(engine.buildExplanation(result))}</p></div><div class="fd-evaluation"><span><b>Post-decision evaluation</b> · Ground truth: ${escapeHtml(result.actualLabel)}</span><strong class="${statusClass(result.evaluation==='FRAUD_MISSED'||result.evaluation==='FALSE_DECLINE'?'DECLINE':'APPROVE')}">${escapeHtml(result.evaluation.replaceAll('_',' '))}</strong></div><p class="fd-reference">✓ Recalculated first; reference check: ${comparison?'score and initial action match expected output':'difference found'}.</p>`;}
  function renderSignals(){const risks=result.signals.filter(item=>item.points>0).sort((a,b)=>b.points-a.points);const protections=result.signals.filter(item=>item.points<0);const group=(title,items,protective)=>`<div class="fd-signal-group ${protective?'fd-protective':''}"><h4>${title}</h4>${items.length?items.map(item=>`<div><span><b>${item.points>0?'+':''}${item.points}</b> ${escapeHtml(item.label)}</span><small>${escapeHtml(item.detail)}</small></div>`).join(''):'<p>No material risk-increasing signals.</p>'}</div>`;el('signal-count').textContent=`${result.signals.length} signals`;el('signal-content').innerHTML=group('Risk-increasing',risks,false)+group('Risk-reducing',protections,true);}
  function renderVerification(){const panel=el('verification');if(result.initialAction!=='VERIFY'){panel.hidden=true;return;}panel.hidden=false;const pending=result.finalAction==='PENDING_VERIFICATION',approved=result.finalAction==='APPROVE';panel.innerHTML=`<div class="fd-verify-question"><small>CUSTOMER VERIFICATION · SIMULATED</small><h3 id="verification-title">Was this purchase made by you?</h3><p>Verification creates a middle path before a final decline.</p><dl><div><dt>Merchant</dt><dd>${escapeHtml(transaction.merchant_name)}</dd></div><div><dt>Amount</dt><dd>${exactMoney.format(Number(transaction.amount_usd))}</dd></div><div><dt>Location</dt><dd>${escapeHtml(transaction.city)}, ${escapeHtml(transaction.state_or_region)}</dd></div></dl><div class="fd-actions"><button type="button" data-response="YES" class="fd-yes">✓ Yes, this was me</button><button type="button" data-response="NO" class="fd-no">× No, this wasn’t me</button></div><button type="button" class="fd-text-button" data-response="${escapeHtml(transaction.customer_verification_response)}">Use simulated response: ${escapeHtml(transaction.customer_verification_response)}</button></div><div class="fd-verify-result ${pending?'fd-pending':approved?'fd-approved-result':'fd-blocked-result'}">${pending?'<small>FINAL RESULT</small><h3>Awaiting customer response</h3><p>The transaction is paused; no final action has been taken.</p>':approved?'<strong class="fd-status fd-approve-text">✓ APPROVE</strong><h3>Transaction approved</h3><ul><li>Purchase allowed</li><li>Card remains active</li><li>Feedback captured</li></ul>':'<strong class="fd-status fd-decline-text">× DECLINE</strong><h3>Transaction blocked</h3><ul><li>Transaction declined</li><li>Card locked</li><li>Fraud case initiated</li><li>Digital replacement card available</li></ul>'}<small>Demonstration behavior only — no live banking action occurs.</small></div>`;panel.querySelectorAll('[data-response]').forEach(button=>button.addEventListener('click',()=>{result=engine.evaluateTransaction(transaction,button.dataset.response);renderScore();renderVerification();}));}
  function renderAll(){renderDetails();renderScore();renderSignals();renderVerification();el('demo-output').setAttribute('aria-busy','false');}
  function updateFlow(stage){document.querySelectorAll('.fd-flow li').forEach(item=>{const number=Number(item.dataset.stage);item.className=number<stage?'fd-complete':number===stage?'fd-active':'';item.querySelector(':scope > span').textContent=number<stage?'✓':number;});}
  function selectScenario(scenario){const list=rowsFor(scenario);transaction=list[indexes[scenario]||0];el('scenario-select').value=scenario;el('scenario-summary').innerHTML=`<strong>${scenarioMeta[scenario][1]}</strong> · ${scenario.replaceAll('_',' ')}`;const scored=engine.scoreTransaction(transaction);result=engine.evaluateTransaction(transaction,scored.initialAction==='VERIFY'?'':transaction.customer_verification_response);renderAll();updateFlow(4);const url=new URL(location.href);url.searchParams.set('scenario',scenario);history.replaceState({},'',url);}
  function next(){const scenario=el('scenario-select').value;const list=rowsFor(scenario);indexes[scenario]=((indexes[scenario]||0)+1)%list.length;selectScenario(scenario);}
  async function init(){try{const response=await fetch('sample_debit_card_transactions.csv');if(!response.ok)throw new Error(`HTTP ${response.status}`);transactions=engine.parseCsv(await response.text());if(!transactions.length)throw new Error('No synthetic transactions are available');el('scenario-select').disabled=false;el('data-status').textContent=`${transactions.length} synthetic transactions ready`;const requested=new URLSearchParams(location.search).get('scenario');selectScenario(order.includes(requested)?requested:order[0]);}catch(error){el('data-status').textContent=`Unable to load synthetic transaction data: ${error.message}`;el('data-status').classList.add('fd-error');}}
  el('scenario-select').addEventListener('change',event=>selectScenario(event.target.value));el('next-transaction').addEventListener('click',next);init();
}());
